// gh-1249: the Checks-API write transport used to inline its token
// swap/restore in every PATCH helper (gh-848 belt, gh-998 sweep, gh-857
// conclusion — three identical copies). The check-runs belong to the
// github-actions App, so each PATCH rides the checks-app token with
// checks:write; the tick PAT would 403.
// Returns { sourceTok, swapped } for the matching restoreChecksToken().
function swapToChecksToken(warnPrefix) {
   var appToken = checksAppToken();
   var sourceTok = (RUN_JOB_PARAMS || {}).sourceToken;
   var swapped = false;
   if (appToken) {
       try {
           set_env_variable('GH_TOKEN', appToken);
           swapped = true;
       } catch (eSwap) {
           console.warn(warnPrefix + (eSwap.message || eSwap));
       }
