// The ePatch catch contract shared by the PATCH loops: the FIRST failure
// message wins, later ones are tallied by the caller's retry-next-tick.
function recordFirstRejection(out, err) {
   if (!out.rejected) out.rejected = (err && err.message) || String(err);
}
